212→  async onModuleInit(): Promise<void> {
213→    // Attempt an immediate collection; log and continue if DB isn't ready yet
214→    await this.collectGauges().catch((err: unknown) => {
215→      this.logger.warn(
216→        `Initial gauge collection failed: ${err instanceof Error ? err.message : String(err)}`
217→      );
218→    });
219→    this.collectInterval = setInterval(() => {
220→      this.collectGauges().catch((err: unknown) => {
221→        this.logger.warn(
222→          `Gauge collection failed: ${err instanceof Error ? err.message : String(err)}`
223→        );
224→      });
225→    }, 30_000);
226→    this.logger.log('Prometheus metrics initialized (collecting gauges every 30s)');
227→  }
228→
229→  onModuleDestroy(): void {
230→    if (this.collectInterval) {
231→      clearInterval(this.collectInterval);
232→    }
233→  }
234→
235→  async getMetrics(): Promise<string> {
236→    return this.registry.metrics();
237→  }
238→
239→  getContentType(): string {
240→    return this.registry.contentType;
241→  }
242→
243→  private async collectGauges(): Promise<void> {
244→    const [userCount, fileStats, ipnsByType, republishByStatus] = await Promise.all([
245→      this.userRepository.count(),
246→      this.pinnedCidRepository
247→        .createQueryBuilder('pin')
248→        .select('COUNT(*)', 'count')
249→        .addSelect('COALESCE(SUM(pin.size_bytes), 0)', 'totalBytes')
250→        .getRawOne<{ count: string; totalBytes: string }>(),
251→      this.folderIpnsRepository
252→        .createQueryBuilder('ipns')
253→        .select('ipns.record_type', 'recordType')
254→        .addSelect('COUNT(*)', 'count')
255→        .groupBy('ipns.record_type')
256→        .getRawMany<{ recordType: string; count: string }>(),
257→      this.republishScheduleRepository
258→        .createQueryBuilder('sched')
259→        .select('sched.status', 'status')
260→        .addSelect('COUNT(*)', 'count')
261→        .groupBy('sched.status')
262→        .getRawMany<{ status: string; count: string }>(),
263→    ]);
264→
265→    this.usersTotal.set(userCount);
266→    this.filesTotal.set(parseInt(fileStats?.count ?? '0', 10));
267→    this.storageBytesTotal.set(parseInt(fileStats?.totalBytes ?? '0', 10));
268→
269→    // Reset IPNS gauges before setting to avoid stale labels
270→    this.ipnsEntriesTotal.reset();
271→    for (const row of ipnsByType) {
272→      this.ipnsEntriesTotal.labels(row.recordType).set(parseInt(row.count, 10));
273→    }
274→
275→    // Reset republish gauges before setting
276→    this.republishScheduleTotal.reset();
277→    for (const row of republishByStatus) {
278→      this.republishScheduleTotal.labels(row.status).set(parseInt(row.count, 10));
279→    }
280→  }
281→}
