 34→
 35→const MAX_FILE_SIZE = 100 * 1024 * 1024; // 100MB
 36→
 37→@ApiTags('IPFS')
 38→@ApiBearerAuth()
 39→@UseGuards(JwtAuthGuard)
 40→@Controller('ipfs')
 41→export class IpfsController {
 42→  constructor(
 43→    @Inject(IPFS_PROVIDER) private readonly ipfsProvider: IpfsProvider,
 44→    private readonly vaultService: VaultService,
 45→    private readonly metricsService: MetricsService
 46→  ) {}
 47→
 48→  @Post('upload')
 49→  @ApiOperation({
 50→    summary: 'Upload encrypted file to IPFS with quota tracking',
 51→    description:
 52→      'Pins encrypted file to IPFS, checks storage quota, and records the pin for quota tracking. All in one atomic request.',
 53→  })
 54→  @ApiConsumes('multipart/form-data')
 55→  @ApiBody({
 56→    schema: {
 57→      type: 'object',
 58→      properties: {
 59→        file: {
 60→          type: 'string',
 61→          format: 'binary',
 62→          description: 'Encrypted file blob (max 100MB)',
 63→        },
 64→      },
 65→      required: ['file'],
 66→    },
 67→  })
 68→  @ApiResponse({
 69→    status: 201,
 70→    description: 'File uploaded, pinned, and recorded successfully',
 71→    type: UploadResponseDto,
 72→  })
 73→  @ApiResponse({
 74→    status: 401,
 75→    description: 'Unauthorized - JWT token required',
 76→  })
 77→  @ApiResponse({
 78→    status: 413,
 79→    description: 'Storage quota exceeded',
 80→  })
 81→  @UseInterceptors(
 82→    FileInterceptor('file', {
 83→      limits: { fileSize: MAX_FILE_SIZE },
 84→    })
 85→  )
 86→  async upload(
 87→    @Request() req: RequestWithUser,
 88→    @UploadedFile(
 89→      new ParseFilePipe({
 90→        validators: [new MaxFileSizeValidator({ maxSize: MAX_FILE_SIZE })],
 91→      })
 92→    )
 93→    file: Express.Multer.File
 94→  ): Promise<UploadResponseDto> {
 95→    const hasQuota = await this.vaultService.checkQuota(req.user.id, file.size);
 96→    if (!hasQuota) throw new PayloadTooLargeException('Storage quota exceeded');
 97→
 98→    const endPinTimer = this.metricsService.ipfsIpnsDuration.startTimer({
 99→      operation: 'pin',
100→      source: '',
101→    });
102→    let result: { cid: string; size: number };
103→    try {
104→      result = await this.ipfsProvider.pinFile(file.buffer);
105→      endPinTimer({ result: 'success' });
106→    } catch (err) {
107→      endPinTimer({ result: 'error' });
108→      throw err;
109→    }
110→
111→    try {
112→      await this.vaultService.recordPin(req.user.id, result.cid, result.size);
113→    } catch (err) {
114→      await this.ipfsProvider.unpinFile(result.cid).catch(() => undefined);
115→      throw err;
116→    }
117→    this.metricsService.fileUploads.inc();
118→    this.metricsService.fileUploadBytes.inc(result.size);
119→    return { cid: result.cid, size: result.size, recorded: true };
120→  }
121→
122→  @Post('unpin')
123→  @ApiOperation({
124→    summary: 'Unpin file from IPFS',
125→    description: 'Remove a pinned file from IPFS using its CID.',
126→  })
127→  @ApiResponse({
128→    status: 201,
129→    description: 'File unpinned successfully',
130→    type: UnpinResponseDto,
131→  })
132→  @ApiResponse({
133→    status: 401,
134→    description: 'Unauthorized - JWT token required',
135→  })
136→  async unpin(@Body() dto: UnpinDto): Promise<UnpinResponseDto> {
137→    await this.ipfsProvider.unpinFile(dto.cid);
138→    this.metricsService.fileUnpins.inc();
139→    return { success: true };
140→  }
141→
142→  @Get(':cid')
143→  @ApiOperation({
144→    summary: 'Get file from IPFS',
145→    description: 'Download an encrypted file from IPFS via the configured gateway.',
146→  })
147→  @ApiResponse({
148→    status: 200,
149→    description: 'File retrieved successfully',
150→    content: {
151→      'application/octet-stream': {
152→        schema: {
153→          type: 'string',
154→          format: 'binary',
155→        },
156→      },
157→    },
158→  })
159→  @ApiResponse({
160→    status: 401,
161→    description: 'Unauthorized - JWT token required',
162→  })
163→  @ApiResponse({
164→    status: 404,
165→    description: 'File not found',
166→  })
167→  async get(
168→    @Param('cid') cid: string,
169→    @Res({ passthrough: true }) res: Response
170→  ): Promise<StreamableFile> {
171→    const endCatTimer = this.metricsService.ipfsIpnsDuration.startTimer({
172→      operation: 'cat',
173→      source: '',
174→    });
175→    let buffer: Buffer;
176→    try {
177→      buffer = await this.ipfsProvider.getFile(cid);
178→      endCatTimer({ result: 'success' });
179→    } catch (err) {
180→      endCatTimer({ result: 'error' });
181→      throw err;
182→    }
183→
184→    this.metricsService.fileDownloads.inc();
185→    res.set({
186→      'Content-Type': 'application/octet-stream',
187→      'Content-Length': buffer.length.toString(),
188→    });
189→    return new StreamableFile(buffer);
190→  }
191→}
