 15→/**
 16→ * Load Test — Concurrent Users Against Staging
 17→ *
 18→ * Each client gets a unique wallet (keypair) injected via EIP-6963 mock provider.
 19→ * Full auth flow: wallet → SIWE sign → Core Kit → key reconstruction → vault init.
 20→ * Then drives ~50+ file operations that each trigger IPNS publishes.
 21→ *
 22→ * Usage:
 23→ *   cd tests/web-e2e
 24→ *   pnpm exec playwright test tests/load-test.spec.ts --config=playwright.load.config.ts
 25→ *
 26→ * Env vars:
 27→ *   LOAD_TEST_CLIENTS=5   Number of concurrent clients (default: 3)
 28→ */
 29→
 30→const NUM_CLIENTS = parseInt(process.env.LOAD_TEST_CLIENTS ?? '5', 10);
 31→
 32→// Generous timeouts — multiple clients hitting staging concurrently
 33→test.setTimeout(600_000); // 10 minutes
