 35→interface LoadClient {
 36→  id: number;
 37→  account: PrivateKeyAccount;
 38→  page: Page;
 39→  context: Awaited<ReturnType<Browser['newContext']>>;
 40→  fileList: FileListPage;
 41→  uploadZone: UploadZonePage;
 42→  contextMenu: ContextMenuPage;
 43→  breadcrumbs: BreadcrumbsPage;
 44→  selectionBar: SelectionActionBarPage;
