 51→// Operation timeout — each individual UI action
 52→const OP_TIMEOUT = 30_000;
 53→
 54→// ─── Helpers ───────────────────────────────────────────────────────────────
 55→
 56→/**
 57→ * Recover page to a known state: dismiss any open modals/menus, navigate to root.
 58→ * Called after a failed op to prevent cascading failures.
 59→ */
 60→async function resetState(client: LoadClient): Promise<void> {
 61→  try {
 62→    // Press Escape a few times to dismiss modals/menus/dialogs
 63→    for (let i = 0; i < 3; i++) {
 64→      await client.page.keyboard.press('Escape');
 65→      await client.page.waitForTimeout(200);
 66→    }
 67→    // Click on an empty area to deselect
 68→    await client.page.mouse.click(0, 0);
 69→    await client.page.waitForTimeout(300);
 70→    // Navigate to root if breadcrumbs are visible
 71→    const breadcrumbVisible = await client.breadcrumbs
 72→      .container()
 73→      .isVisible()
 74→      .catch(() => false);
 75→    if (breadcrumbVisible) {
 76→      await client.breadcrumbs.clickBreadcrumb('my vault').catch(() => {});
 77→      await client.page.waitForTimeout(1000);
 78→    }
 79→  } catch {
 80→    // Best-effort reset — if the page is completely broken, subsequent ops will also fail
 81→  }
 82→}
 83→
 84→/** Safe wrapper for operations — logs failures but doesn't abort the run */
 85→async function op(
 86→  client: LoadClient,
 87→  description: string,
 88→  fn: () => Promise<void>
 89→): Promise<boolean> {
 90→  try {
 91→    await fn();
 92→    console.log(`    [C${client.id}] ✓ ${description}`);
 93→    return true;
 94→  } catch (err) {
 95→    console.warn(`    [C${client.id}] ✗ ${description}: ${(err as Error).message.slice(0, 120)}`);
 96→    await resetState(client);
 97→    return false;
 98→  }
 99→}
