132→/** Right-click → Rename */
133→async function renameItem(client: LoadClient, oldName: string, newName: string): Promise<void> {
134→  await client.fileList.rightClickItem(oldName);
135→  await client.contextMenu.waitForOpen({ timeout: 5000 });
136→  await client.contextMenu.clickRename();
