166→/** Delete account by calling the API from within the page context.
167→ *  Uses fetch with credentials to send the refresh token cookie,
168→ *  gets a fresh access token, then calls DELETE /auth/account. */
169→async function deleteAccount(client: LoadClient): Promise<void> {
170→  // Discover the API base URL from the app's runtime config
171→  const apiBase = await client.page.evaluate(() => {
172→    // Vite injects env vars at build time — read from the same source as apiClient
173→    return (
174→      (window as Record<string, string>).__VITE_API_URL ||
175→      document.querySelector('meta[name="api-url"]')?.getAttribute('content') ||
176→      'https://api-staging.cipherbox.cc'
177→    );
178→  });
179→
180→  const deleted = await client.page.evaluate(async (apiUrl: string) => {
181→    // Step 1: Refresh to get a fresh access token (uses HTTP-only cookie)
182→    const refreshRes = await fetch(`${apiUrl}/auth/refresh`, {
183→      method: 'POST',
184→      credentials: 'include',
185→    });
186→    if (!refreshRes.ok) return { ok: false, step: 'refresh', status: refreshRes.status };
187→    const { accessToken } = await refreshRes.json();
188→
189→    // Step 2: Delete the account
190→    const deleteRes = await fetch(`${apiUrl}/auth/account`, {
191→      method: 'DELETE',
192→      credentials: 'include',
193→      headers: {
194→        Authorization: `Bearer ${accessToken}`,
195→        'Content-Type': 'application/json',
196→      },
197→      body: JSON.stringify({ confirmation: 'DELETE' }),
198→    });
199→    return { ok: deleteRes.ok, step: 'delete', status: deleteRes.status };
200→  }, apiBase);
201→
202→  if (!deleted.ok) {
203→    throw new Error(`Account deletion failed at ${deleted.step}: HTTP ${deleted.status}`);
204→  }
205→}
