245→// ─── Main client workload ──────────────────────────────────────────────────
246→
247→/**
248→ * Full workload for a single client. ~50+ operations, each triggering IPNS publish.
249→ *
250→ * Structure:
251→ *   Phase 1: Create folder hierarchy (5 folders + 2 subfolders)     →  7 publishes
252→ *   Phase 2: Upload small text files (15 files across folders)      → 15 publishes
253→ *   Phase 3: Upload medium binary files (10 files)                  → 10 publishes
254→ *   Phase 4: Upload large binary files (5 files, 100KB–500KB)       →  5 publishes
255→ *   Phase 5: Edit text files (5 edits)                              →  5 publishes
256→ *   Phase 6: Rename items (8 renames: files + folders)              →  8 publishes
257→ *   Phase 7: Move items between folders (6 individual moves)        →  6 publishes
258→ *   Phase 8: Batch move (2 batches of 3 files)                      →  2 publishes
259→ *   Phase 9: Batch delete (2 batches of 3–4 files)                  →  2 publishes
260→ *   Phase 10: Individual deletes + cleanup (remaining items)        → ~10 publishes
261→ *                                                             Total: ~70 publishes
262→ */
263→async function runClientWorkload(
264→  client: LoadClient
265→): Promise<{ succeeded: number; failed: number }> {
266→  const { id } = client;
267→  const prefix = `c${id}`;
268→  let succeeded = 0;
269→  let failed = 0;
270→
271→  const count = (ok: boolean) => {
272→    if (ok) succeeded++;
273→    else failed++;
274→  };
275→
276→  // ─── Warm-up: first mutation after login races with initial sync polling.
277→  // Create and delete a dummy folder to let the sync settle.
278→  await op(client, 'Warm-up folder', async () => {
279→    await createFolder(client, `${prefix}-warmup`);
280→    await deleteItem(client, `${prefix}-warmup`);
281→  });
282→
283→  // ─── Phase 1: Create folder hierarchy ────────────────────────────────
284→  console.log(`  [C${id}] Phase 1: Creating folder hierarchy...`);
285→
286→  const folders = ['docs', 'images', 'data', 'archive', 'temp'];
287→  const folderNames = folders.map((f) => `${prefix}-${f}`);
288→
289→  for (const name of folderNames) {
290→    count(await op(client, `Create folder ${name}`, () => createFolder(client, name)));
291→  }
292→
293→  // Create subfolders inside 'docs' and 'data'
294→  const subfolders = [
295→    { parent: folderNames[0], name: `${prefix}-docs-sub` },
296→    { parent: folderNames[2], name: `${prefix}-data-sub` },
297→  ];
298→  for (const sub of subfolders) {
299→    count(
300→      await op(client, `Create subfolder ${sub.name}`, async () => {
301→        await enterFolder(client, sub.parent);
302→        await createFolder(client, sub.name);
303→        await goToRoot(client);
304→      })
305→    );
306→  }
307→
308→  // ─── Phase 2: Upload small text files ────────────────────────────────
309→  console.log(`  [C${id}] Phase 2: Uploading 15 small text files...`);
310→
311→  const textFiles: { name: string; path: string; folder: string | null }[] = [];
312→  // 5 files at root
313→  for (let i = 1; i <= 5; i++) {
314→    const f = createTestTextFile(
315→      `${prefix}-note-${i}.txt`,
316→      `Client ${id} note ${i}. Timestamp: ${Date.now()}. ${'Lorem ipsum dolor sit amet. '.repeat(10)}`
317→    );
318→    textFiles.push({ name: f.name, path: f.path, folder: null });
319→  }
320→  // 5 files in docs folder
321→  for (let i = 1; i <= 5; i++) {
322→    const f = createTestTextFile(
323→      `${prefix}-doc-${i}.txt`,
324→      `Document ${i} from client ${id}. ${'Content block. '.repeat(20)}`
325→    );
326→    textFiles.push({ name: f.name, path: f.path, folder: folderNames[0] });
327→  }
328→  // 5 files in data folder
329→  for (let i = 1; i <= 5; i++) {
330→    const f = createTestTextFile(
331→      `${prefix}-log-${i}.txt`,
332→      `Log entry ${i}: ${new Date().toISOString()} client=${id} ${'data '.repeat(50)}`
333→    );
334→    textFiles.push({ name: f.name, path: f.path, folder: folderNames[2] });
335→  }
336→
337→  // Upload root files
338→  for (const tf of textFiles.filter((f) => !f.folder)) {
339→    count(await op(client, `Upload ${tf.name}`, () => uploadFile(client, tf.path, tf.name)));
340→  }
341→  // Upload into docs
342→  count(
343→    await op(client, `Navigate to ${folderNames[0]}`, () => enterFolder(client, folderNames[0]))
344→  );
345→  for (const tf of textFiles.filter((f) => f.folder === folderNames[0])) {
346→    count(await op(client, `Upload ${tf.name}`, () => uploadFile(client, tf.path, tf.name)));
347→  }
348→  count(await op(client, 'Back to root', () => goToRoot(client)));
349→
350→  // Upload into data
351→  count(
352→    await op(client, `Navigate to ${folderNames[2]}`, () => enterFolder(client, folderNames[2]))
353→  );
354→  for (const tf of textFiles.filter((f) => f.folder === folderNames[2])) {
355→    count(await op(client, `Upload ${tf.name}`, () => uploadFile(client, tf.path, tf.name)));
356→  }
357→  count(await op(client, 'Back to root', () => goToRoot(client)));
358→
359→  // ─── Phase 3: Upload medium binary files ─────────────────────────────
360→  console.log(`  [C${id}] Phase 3: Uploading 10 medium binary files (10–50KB)...`);
361→
362→  const mediumFiles: { name: string; path: string }[] = [];
363→  for (let i = 1; i <= 10; i++) {
364→    const sizeKb = 10 + Math.floor(Math.random() * 40); // 10-50KB
365→    const f = createTestBinaryFile(sizeKb, `${prefix}-medium-${i}.bin`);
366→    mediumFiles.push({ name: f.name, path: f.path });
367→  }
368→
369→  // Upload half to root, half to images folder
370→  for (const mf of mediumFiles.slice(0, 5)) {
371→    count(await op(client, `Upload ${mf.name}`, () => uploadFile(client, mf.path, mf.name)));
372→  }
373→  count(
374→    await op(client, `Navigate to ${folderNames[1]}`, () => enterFolder(client, folderNames[1]))
375→  );
376→  for (const mf of mediumFiles.slice(5)) {
377→    count(await op(client, `Upload ${mf.name}`, () => uploadFile(client, mf.path, mf.name)));
378→  }
379→  count(await op(client, 'Back to root', () => goToRoot(client)));
380→
381→  // ─── Phase 4: Upload large binary files ──────────────────────────────
382→  console.log(`  [C${id}] Phase 4: Uploading 5 large binary files (100–500KB)...`);
383→
384→  const largeFiles: { name: string; path: string }[] = [];
385→  const largeSizes = [100, 200, 300, 400, 500];
386→  for (let i = 0; i < 5; i++) {
387→    const f = createTestBinaryFile(largeSizes[i], `${prefix}-large-${i + 1}.bin`);
388→    largeFiles.push({ name: f.name, path: f.path });
389→  }
390→
391→  for (const lf of largeFiles) {
392→    count(
393→      await op(client, `Upload ${lf.name} (${largeSizes[largeFiles.indexOf(lf)]}KB)`, () =>
394→        uploadFile(client, lf.path, lf.name)
395→      )
