397→  }
398→
399→  // ─── Phase 5: Re-upload files (overwrite triggers IPNS publish) ─────
400→  // Text editor dialog is unreliable on staging (IPNS resolve for file
401→  // content hangs). Re-uploading with same filename overwrites the file,
402→  // which equally triggers metadata update + IPNS publish.
403→  console.log(`  [C${id}] Phase 5: Re-uploading 5 files (overwrite)...`);
