405→  for (let i = 1; i <= 5; i++) {
406→    const f = createTestTextFile(
407→      `${prefix}-note-${i}.txt`,
408→      `EDITED by client ${id} at ${new Date().toISOString()}. Revision ${i}.\n${'Updated content block. '.repeat(30)}`
409→    );
410→    count(await op(client, `Re-upload ${f.name}`, () => uploadFile(client, f.path, f.name)));
411→  }
412→
413→  // ─── Phase 6: Rename items ───────────────────────────────────────────
414→  console.log(`  [C${id}] Phase 6: Renaming 8 items...`);
415→
416→  // Rename 5 root files
417→  for (let i = 1; i <= 5; i++) {
418→    const oldName = `${prefix}-note-${i}.txt`;
