421→      await op(client, `Rename ${oldName} → ${newName}`, () => renameItem(client, oldName, newName))
422→    );
423→  }
424→
425→  // Rename 2 folders
426→  count(
427→    await op(client, `Rename folder ${folderNames[4]}`, () =>
428→      renameItem(client, folderNames[4], `${prefix}-renamed-temp`)
429→    )
430→  );
431→  count(
432→    await op(client, `Rename folder ${folderNames[3]}`, () =>
433→      renameItem(client, folderNames[3], `${prefix}-renamed-archive`)
434→    )
435→  );
436→
437→  // Rename a large file
438→  count(
439→    await op(client, `Rename ${largeFiles[0].name}`, () =>
440→      renameItem(client, largeFiles[0].name, `${prefix}-renamed-large.bin`)
441→    )
442→  );
443→
444→  // ─── Phase 7: Move items between folders ─────────────────────────────
445→  console.log(`  [C${id}] Phase 7: Moving 6 items individually...`);
446→
447→  // Move renamed notes into docs folder
448→  for (let i = 1; i <= 3; i++) {
449→    const fileName = `${prefix}-renamed-note-${i}.txt`;
450→    count(
451→      await op(client, `Move ${fileName} → ${folderNames[0]}`, () =>
