455→  }
456→
457→  // Move medium files into renamed-archive
458→  for (let i = 1; i <= 3; i++) {
459→    const fileName = mediumFiles[i - 1].name;
460→    count(
461→      await op(client, `Move ${fileName} → ${prefix}-renamed-archive`, () =>
462→        moveItem(client, fileName, `${prefix}-renamed-archive`)
463→      )
464→    );
465→  }
466→
467→  // ─── Phase 8: Batch move ─────────────────────────────────────────────
468→  console.log(`  [C${id}] Phase 8: Batch moving files...`);
469→
470→  // Batch move remaining medium root files into renamed-temp
471→  const remainingMedium = mediumFiles.slice(3, 5).map((f) => f.name);
472→  if (remainingMedium.length >= 2) {
473→    count(
474→      await op(client, `Batch move ${remainingMedium.length} files → ${prefix}-renamed-temp`, () =>
475→        batchMove(client, remainingMedium, `${prefix}-renamed-temp`)
476→      )
477→    );
478→  }
479→
480→  // Batch move large files (2-4) into data folder
481→  const largesToMove = largeFiles.slice(1, 4).map((f) => f.name);
482→  if (largesToMove.length >= 2) {
483→    count(
484→      await op(client, `Batch move ${largesToMove.length} large files → ${folderNames[2]}`, () =>
485→        batchMove(client, largesToMove, folderNames[2])
486→      )
487→    );
488→  }
489→
490→  // ─── Phase 9: Batch delete ───────────────────────────────────────────
491→  console.log(`  [C${id}] Phase 9: Batch deleting files...`);
492→
493→  // Navigate to renamed-archive and batch delete the 3 medium files we moved there
494→  count(
495→    await op(client, `Navigate to ${prefix}-renamed-archive`, () =>
496→      enterFolder(client, `${prefix}-renamed-archive`)
497→    )
498→  );
499→  const archiveFiles = mediumFiles.slice(0, 3).map((f) => f.name);
500→  if (archiveFiles.length >= 2) {
501→    count(
502→      await op(client, `Batch delete ${archiveFiles.length} files from archive`, () =>
503→        batchDelete(client, archiveFiles)
504→      )
505→    );
506→  }
507→  count(await op(client, 'Back to root', () => goToRoot(client)));
508→
509→  // Navigate to data folder and batch delete log files
510→  count(
511→    await op(client, `Navigate to ${folderNames[2]}`, () => enterFolder(client, folderNames[2]))
512→  );
513→  const dataLogFiles = [`${prefix}-log-1.txt`, `${prefix}-log-2.txt`, `${prefix}-log-3.txt`];
514→  count(
515→    await op(client, `Batch delete ${dataLogFiles.length} log files`, () =>
516→      batchDelete(client, dataLogFiles)
517→    )
518→  );
519→  count(await op(client, 'Back to root', () => goToRoot(client)));
520→
521→  // ─── Phase 10: Individual cleanup deletes ────────────────────────────
522→  console.log(`  [C${id}] Phase 10: Cleaning up remaining items...`);
523→
524→  // Delete remaining root items one by one
525→  const rootCleanup = [
526→    `${prefix}-renamed-note-4.txt`,
527→    `${prefix}-renamed-note-5.txt`,
528→    `${prefix}-renamed-large.bin`,
529→    largeFiles[4].name, // large-5 still at root
530→  ];
531→  for (const item of rootCleanup) {
532→    count(await op(client, `Delete ${item}`, () => deleteItem(client, item)));
533→  }
534→
535→  // Delete folders (cascading — contents deleted with folder)
536→  const foldersToDelete = [
537→    folderNames[0], // docs (has subfolders + files)
538→    folderNames[1], // images (has medium files)
539→    folderNames[2], // data (has subfolder + log files + large files)
540→    `${prefix}-renamed-archive`,
541→    `${prefix}-renamed-temp`,
542→  ];
543→  for (const folder of foldersToDelete) {
544→    count(await op(client, `Delete folder ${folder}`, () => deleteItem(client, folder)));
545→  }
546→
547→  return { succeeded, failed };
548→}
